module graph_coloring (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] adj_0,\n    input wire [7:0] adj_1,\n    input wire [7:0] adj_2,\n    input wire [7:0] adj_3,\n    input wire [7:0] adj_4,\n    input wire [7:0] adj_5,\n    input wire [7:0] adj_6,\n    input wire [7:0] adj_7,\n    output reg [3:0] result,\n    output reg done\n);\n\nlocalparam [3:0] S_IDLE = 4'd0, S_START_K = 4'd1, S_NEXT_VERT = 4'd2;\nlocalparam [3:0] S_CHECK_COLOR = 4'd3, S_VALIDATE = 4'd4, S_BACKTRACK = 4'd5;\nlocalparam [3:0] S_SUCCESS = 4'd6, S_FAIL = 4'd7, S_DONE = 4'd8;\n\nlocalparam MAX_VERTICES = 8;\nlocalparam MAX_COLORS = 8;\n\nreg [3:0] state;\nreg [3:0] k;\nreg [2:0] vertex_idx;\nreg [2:0] color_try;\nreg [7:0] adj [0:7];\nreg [2:0] colors [0:7];\nreg [7:0] colored_mask;\nreg [2:0] stack_vertex [0:7];\nreg [2:0] stack_color [0:7];\nreg [2:0] stack_ptr;\n\ninteger i;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= S_IDLE;\n        done <= 1'b0;\n        result <= 4'd0;\n        k <= 4'd1;\n        vertex_idx <= 3'd0;\n        color_try <= 3'd0;\n        colored_mask <= 8'd0;\n        stack_ptr <= 3'd0;\n        for (i = 0; i < 8; i = i + 1) begin\n            adj[i] <= 8'd0;\n            colors[i] <= 3'd0;\n            stack_vertex[i] <= 3'd0;\n            stack_color[i] <= 3'd0;\n        end\n    end else begin\n        case (state)\n            S_IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    k <= 4'd1;\n                    adj[0] <= adj_0;\n                    adj[1] <= adj_1;\n                    adj[2] <= adj_2;\n                    adj[3] <= adj_3;\n                    adj[4] <= adj_4;\n                    adj[5] <= adj_5;\n                    adj[6] <= adj_6;\n                    adj[7] <= adj_7;\n                    state <= S_START_K;\n                end\n            end\n            \n            S_START_K: begin\n                vertex_idx <= 3'd0;\n                color_try <= 3'd0;\n                colored_mask <= 8'd0;\n                stack_ptr <= 3'd0;\n                state <= S_NEXT_VERT;\n            end\n            \n            S_NEXT_VERT: begin\n                if (vertex_idx == 3'd7) state <= S_SUCCESS;\n                else if (vertex_idx < 3'd7) begin\n                    vertex_idx <= vertex_idx + 3'd1;\n                    color_try <= 3'd0;\n                    state <= S_CHECK_COLOR;\n                end else state <= S_IDLE;\n            end\n            \n            S_CHECK_COLOR: begin\n                if (color_try >= k) state <= S_BACKTRACK;\n                else state <= S_VALIDATE;\n            end\n            \n            S_VALIDATE: begin\n                if (is_color_valid(vertex_idx, color_try)) begin\n                    colors[vertex_idx] <= color_try;\n                    colored_mask[vertex_idx] <= 1'b1;\n                    stack_vertex[stack_ptr] <= vertex_idx;\n                    stack_color[stack_ptr] <= color_try;\n                    stack_ptr <= stack_ptr + 3'd1;\n                    state <= S_NEXT_VERT;\n                end else begin\n                    color_try <= color_try + 3'd1;\n                    state <= S_CHECK_COLOR;\n                end\n            end\n            \n            S_BACKTRACK: begin\n                if (stack_ptr == 3'd0) begin\n                    if (k >= MAX_COLORS) begin\n                        result <= MAX_COLORS;\n                        state <= S_DONE;\n                    end else begin\n                        k <= k + 4'd1;\n                        state <= S_START_K;\n                    end\n                end else begin\n                    stack_ptr <= stack_ptr - 3'd1;\n                    colored_mask[stack_vertex[stack_ptr]] <= 1'b0;\n                    vertex_idx <= stack_vertex[stack_ptr];\n                    color_try <= stack_color[stack_ptr] + 3'd1;\n                    state <= S_CHECK_COLOR;\n                end\n            end\n            \n            S_SUCCESS: begin\n                result <= k;\n                state <= S_DONE;\n            end\n            \n            S_FAIL: begin\n                result <= MAX_COLORS;\n                state <= S_DONE;\n            end\n            \n            S_DONE: begin\n                done <= 1'b1;\n                state <= S_IDLE;\n            end\n            \n            default: state <= S_IDLE;\n        endcase\n    end\nend\n\nfunction automatic reg is_color_valid(input [2:0] v, input [2:0] c);\n    integer j;\nbegin\n    is_color_valid = 1'b1;\n    for (j = 0; j < MAX_VERTICES; j = j + 1) begin\n        if (adj[v][j] && colored_mask[j] && (colors[j] == c)) begin\n            is_color_valid = 1'b0;\n        end\n    end\nend\nendfunction\n\nendmodule